<?php class AsistenciaModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;} function obtenerTodas(){return $this->pdo->query("SELECT a.*,CONCAT(u.nombre,' ',u.apellido) estudiante,c.nombre_curso,c.codigo FROM asistencia a JOIN inscripciones i ON i.id_inscripcion=a.id_inscripcion JOIN estudiantes e ON e.id_estudiante=i.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN cursos c ON c.id_curso=i.id_curso ORDER BY a.fecha DESC")->fetchAll();} function obtenerPorId($id){$s=$this->pdo->prepare('SELECT * FROM asistencia WHERE id_asistencia=?');$s->execute([$id]);return $s->fetch();} function crear($d){$s=$this->pdo->prepare('INSERT INTO asistencia(id_inscripcion,fecha,estado,observacion) VALUES(?,?,?,?)');return $s->execute([$d['id_inscripcion'],$d['fecha'],$d['estado'],$d['observacion']]);} function editar($id,$d){$s=$this->pdo->prepare('UPDATE asistencia SET id_inscripcion=?,fecha=?,estado=?,observacion=? WHERE id_asistencia=?');return $s->execute([$d['id_inscripcion'],$d['fecha'],$d['estado'],$d['observacion'],$id]);} function eliminar($id){$s=$this->pdo->prepare('DELETE FROM asistencia WHERE id_asistencia=?');return $s->execute([$id]);}}
